      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"
    }
  }
}

{
  "description": "The decoded software statement retrieved from the Trust Framework that provides\nthe properties of the Client.\n\nPlease note:\n\n  - The JSON payload will contain other properties in addition to those listed\n    here. The properties listed here are considered most relevant for activities\n    such as TPP logo retrieval and JWS verification.\n  - The content reflects elements of discovery metadata, which in generally\n    defined as a file rather than an API. Providing constraints such as\n    `minLength` and `maxLength` is impractical in this context\n\nThe full software statement record is also available in the Trust Framework.\nPlease also refer the Registration Framework page in the CBUAE standards for\nadditional guidance on these properties.\n",
  "type": "object",
  "properties": {
    "redirect_uris": {
      "description": "The redirect URIs registered by the TPP at the Trust Framework",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "client_name": {
      "description": "Name of the Client to be presented to the End-User.",
      "type": "string"
    },
    "client_uri": {
      "description": "URL of the home page of the Client.",
      "type": "string"
    },
    "logo_uri": {
      "description": "URL of the Client logo.",
      "type": "string"
    },
    "jwks_uri": {
      "description": "URL of the Client JSON Web Key Set (JWKS) at the Trust Framework.",
      "type": "string"
    },
    "client_id": {
      "description": "Unique Client Identifier.",
      "type": "string"
    },
    "roles": {
      "description": "The roles under which the organization is registered at the Trust Framework.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "sector_identifier_uri": {
      "description": "URL using the https scheme to be used in calculating Pseudonymous Identifiers by the OP. Allows redirect URI values to be grouped, easing registration management.",
